Section TOP.
Context {O : Type} (pans : O -> aptr -> Z -> Z -> Z) (pupd : O -> ev -> Z -> O).
Local Notation KREL := (KREL pans pupd).
Local Notation BREL := (BREL pans pupd).

Definition CREL : ltac2:(zQ "50!il2!h8!j9!oc!qa>1x@2$0?1O@2$0$4@1$1@2$0$3$2>1y@2$0$4@1$1@2$0$3$2P") := ltac2:(zQ "a1!il2!h8!j9!oc!qa!kh7!hh3!s7!mm9!q2&@3$5?1O@2$0$4@1$1@2$0$3$2^2\1x@2$0?1O@2$0$4@1$1@2$0$3$2\1y@2$0$4@1$1@2$0$3$2@2$8@3$7$4@1$9@3$6$4@1$1@2$0$3$2~0@3$6$4@1$1@2$0$3$2^1@3$7@1$1@2$0$3$2@3$5$4@1$1@2$0$3$2~0@3$5$4@1$1@2$0$3$2^1").

Lemma malloc_small_ctrl_ctrl {R1 R2} (RR : O * R1 -> R2 -> Prop) n k1 k2 b1 b2 :
  KREL RR k1 k2 -> BREL RR b1 b2 ->
  forall o st cst, cst = strip st ->
